import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { AdminService } from '../../services/admin.service';

interface Airport {
  _id?: string;
  _code: string;
  name: string;
  city: string;
}

@Component({
  selector: 'app-admin',
  templateUrl: './admin.component.html',
  styleUrls: ['./admin.component.css']
})
export class AdminComponent implements OnInit {
  inviteForm!: FormGroup;
  airportForm!: FormGroup;

  airports: Airport[] = [];
  editing: { [id: string]: boolean } = {};
  editBuffer: { [id: string]: Airport } = {};

  constructor(private fb: FormBuilder, private adminSvc: AdminService) {}

  ngOnInit(): void {
    this.inviteForm = this.fb.group({
      companyName: ['', Validators.required],
      email: ['', [Validators.required, Validators.email]]
    });

    this.airportForm = this.fb.group({
      _code: ['', Validators.required],
      name: ['', Validators.required],
      city: ['', Validators.required]
    });

    this.loadAirports();
  }

  // ✉️ Invita compagnia
  inviteCompany(): void {
    if (this.inviteForm.invalid) return;
    this.adminSvc.inviteCompany(this.inviteForm.value).subscribe({
      next: res => {
        alert(`Invito inviato a ${res.email} con password temporanea: ${res.tempPassword}`);
        this.inviteForm.reset();
      },
      error: err => alert('Errore invio invito: ' + err.message)
    });
  }

  // 🛫 CRUD aeroporti
  loadAirports(): void {
    this.adminSvc.getAirports().subscribe({
      next: list => this.airports = list,
      error: err => console.error(err)
    });
  }

  addAirport(): void {
    if (this.airportForm.invalid) return;
    this.adminSvc.addAirport(this.airportForm.value).subscribe({
      next: a => {
        this.airports.push(a);
        this.airportForm.reset();
      },
      error: err => alert('Errore creazione aeroporto')
    });
  }

  startEdit(a: Airport): void {
    this.editing[a._id!] = true;
    this.editBuffer[a._id!] = { ...a };
  }

  saveEdit(id: string): void {
    const data = this.editBuffer[id];
    this.adminSvc.updateAirport(id, data).subscribe({
      next: updated => {
        const idx = this.airports.findIndex(a => a._id === id);
        if (idx > -1) this.airports[idx] = updated;
        this.cancelEdit(id);
      },
      error: err => alert('Errore aggiornamento aeroporto')
    });
  }

  cancelEdit(id: string): void {
    delete this.editing[id];
    delete this.editBuffer[id];
  }

  deleteAirport(id: string): void {
    this.adminSvc.deleteAirport(id).subscribe({
      next: () => this.airports = this.airports.filter(a => a._id !== id),
      error: err => alert('Errore eliminazione aeroporto')
    });
  }
}
<div class="admin-container">

  <!-- ✉️ INVITO COMPAGNIA -->
  <section class="card">
    <h2>Invita Compagnia Aerea</h2>
    <form [formGroup]="inviteForm" (ngSubmit)="inviteCompany()">
      <input formControlName="companyName" placeholder="Nome compagnia" />
      <input formControlName="email" placeholder="Email amministratore" />
      <button type="submit" [disabled]="inviteForm.invalid">Invita</button>
    </form>
  </section>

  <!-- 🛫 GESTIONE AEROPORTI -->
  <section class="card">
    <h2>Aeroporti</h2>
    <form [formGroup]="airportForm" (ngSubmit)="addAirport()" class="inline-form">
      <input formControlName="_code" placeholder="Codice (es. FCO)" />
      <input formControlName="name" placeholder="Nome aeroporto" />
      <input formControlName="city" placeholder="Città" />
      <button type="submit" [disabled]="airportForm.invalid">Aggiungi</button>
    </form>

    <table>
      <thead>
        <tr>
          <th>Codice</th>
          <th>Nome</th>
          <th>Città</th>
          <th>Azioni</th>
        </tr>
      </thead>
      <tbody>
        <tr *ngFor="let a of airports">
          <ng-container *ngIf="!editing[a._id!]; else editTpl">
            <td>{{ a._code }}</td>
            <td>{{ a.name }}</td>
            <td>{{ a.city }}</td>
            <td class="actions">
              <button (click)="startEdit(a)">✏️</button>
              <button (click)="deleteAirport(a._id!)">🗑️</button>
            </td>
          </ng-container>
          <ng-template #editTpl>
            <td><input [(ngModel)]="editBuffer[a._id!]._code" /></td>
            <td><input [(ngModel)]="editBuffer[a._id!].name" /></td>
            <td><input [(ngModel)]="editBuffer[a._id!].city" /></td>
            <td class="actions">
              <button (click)="saveEdit(a._id!)">💾</button>
              <button (click)="cancelEdit(a._id!)">❌</button>
            </td>
          </ng-template>
        </tr>
      </tbody>
    </table>
  </section>

</div>
